async (page) => {
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  const checks=[];
  const ok=(condition,label)=>{if(!condition)throw Error(label);checks.push(label);};
  await page.goto('http://127.0.0.1:8767/');
  const f=page.frames().find(frame=>frame!==page.mainFrame());
  const root=f.locator('#evently-premium');
  const button=name=>f.getByRole('button',{name,exact:true});
  const save=async(name,width=390)=>{
    await page.setViewportSize({width,height:1000});
    await f.waitForFunction(w=>innerWidth===w,width-32);
    await f.locator('.ep-body').evaluate(e=>e.scrollTop=0);
    await f.locator('img').evaluateAll(es=>es.forEach(e=>e.loading='eager'));
    const height=await root.evaluate(e=>Math.ceil(e.getBoundingClientRect().height));
    await page.setViewportSize({width,height:height+40});
    await root.screenshot({path:'/Users/sellu/Desktop/event_planner/docs/design/evidence/'+name+'.png'});
  };
  await save('explore-light');
  ok(await f.locator('.ep-section h2').evaluateAll(es=>es.every(e=>parseFloat(getComputedStyle(e).fontSize)<=16)),'Mobile section titles are at most 16px');
  ok(await f.locator('h1').evaluate(e=>parseFloat(getComputedStyle(e).fontSize)<=22),'Mobile page heading is at most 22px');
  ok(await root.evaluate(e=>e.querySelector('.ep-nav').getBoundingClientRect().bottom<=e.getBoundingClientRect().bottom),'Bottom navigation stays inside mobile viewport');
  await button('Start planning').click();
  await button('Birthday').click();
  await f.getByLabel('Give it a name',{exact:false}).fill('Aarav’s birthday');
  await save('plan-event');
  await f.getByRole('button',{name:'Find my event team'}).click();
  await button('View Amber Events').click();
  await button('Next photo').click();
  ok(await f.getByText('2 / 2',{exact:true}).count()===1,'Gallery moves to next photo');
  await button('Previous photo').click();
  await button('Reviews').click();
  ok(await f.getByText('This demo vendor has no customer reviews yet.',{exact:false}).count()===1,'Unrated vendor has honest empty review state');
  await button('About').click();
  await save('vendor-detail');
  await f.getByRole('button',{name:'Choose services'}).click();
  ok(await f.getByRole('button',{name:'Review my selection'}).isDisabled(),'Empty service selection cannot continue');
  await f.getByRole('checkbox',{name:'Select Stage Decor',exact:true}).check();
  ok(await f.locator('input[data-service="1"]').evaluate(e=>document.activeElement===e),'Checkbox keeps keyboard focus after selection');
  await f.getByRole('checkbox',{name:'Select Catering Buffet',exact:true}).check();
  await f.getByRole('checkbox',{name:'Select Event Lighting',exact:true}).check();
  await button('Increase Event Lighting quantity').click();
  ok(await f.locator('[data-total]').textContent()==='₹91,000','Three services total 35000 + 60×850 + 2×2500 = 91000');
  await save('service-builder');
  await f.getByRole('button',{name:'Review my selection'}).click();
  ok(await f.getByText('₹91,000',{exact:true}).count()===1,'Review preserves itemized total');
  await save('request-review');
  await button('Edit').click();
  await button('One service').click();
  await f.getByRole('checkbox',{name:'Select Catering Buffet',exact:true}).check();
  ok(await f.locator('input[data-service]:checked').count()===1,'Single service mode replaces prior selection');
  await f.getByLabel('Plates',{exact:true}).fill('75');
  await f.getByLabel('Plates',{exact:true}).press('Tab');
  ok(await f.locator('[data-total]').textContent()==='₹63,750','Quantity input recalculates 75 plates to 63750');
  await f.getByRole('button',{name:'Review my selection'}).click();
  await f.getByRole('button',{name:'Preview booking request'}).click();
  ok(await f.getByText('No booking request was sent.',{exact:false}).count()===1,'Preview explicitly discloses no real submission');
  await f.getByRole('button',{name:'See my event'}).click();
  await f.getByRole('checkbox',{name:'Shortlist your event team'}).check();
  ok(await f.getByText('1 / 3 done',{exact:true}).count()===1,'Event checklist updates');
  await save('event-workspace');
  await f.getByRole('button',{name:'Add vendor'}).click();
  ok(await f.getByText('20 Mar 2027 · 60 guests · Pune',{exact:true}).count()===1,'Adding vendor preserves event context');
  await button('Save Amber Events').click();
  await button('Saved').click();
  ok(await button('View Amber Events').count()===1,'Saved vendor appears in shortlist');
  await button('Unsave Amber Events').click();
  ok(await f.getByText('Something will catch your eye.',{exact:true}).count()===1,'Unsave restores empty shortlist');
  await button('Explore vendors').click();
  const search=f.getByRole('textbox',{name:'Search occasions, services or vendors'});
  await search.fill('not-a-real-service-xyz');await search.press('Enter');
  ok(await f.getByText('A fresh search?',{exact:true}).count()===1,'Keyboard search produces honest empty result');
  await button('Clear filters').click();
  ok(await f.getByText('11 demo vendors',{exact:true}).count()===1,'Clearing filters restores all 11 vendors');
  await f.getByLabel('Sort vendors').selectOption('low');
  ok((await f.locator('.ep-vendor h3').first().textContent())==='Saffron Table Catering','Price sorting uses catalog starting rate');
  await button('Services').click();
  await button('Photography').click();
  ok(await f.getByText('1 demo vendor',{exact:true}).count()===1,'Category filter selects matching vendor');
  await button('You').click();
  await f.getByLabel('Appearance').selectOption('dark');
  await button('Explore').click();
  await save('explore-dark',390);
  const dark=await root.evaluate(e=>getComputedStyle(e).backgroundColor);
  ok(dark==='rgb(29, 17, 23)','Explicit dark appearance uses dark product surface');
  await button('You').click();await f.getByLabel('Appearance').selectOption('light');await button('Explore').click();
  const layouts=[];
  for(const width of [320,390,736]){
    await page.setViewportSize({width,height:1100});
    await f.waitForFunction(w=>innerWidth===w,width-32);
    const sizes=await root.evaluate(e=>({width:e.clientWidth,scroll:e.scrollWidth,body:document.documentElement.scrollWidth,viewport:innerWidth}));
    ok(sizes.scroll===sizes.width&&sizes.body<=sizes.viewport,`Explore has no horizontal overflow at ${width}px viewport`);
    layouts.push({outerViewport:width,...sizes});
  }
  await button('Your occasion').click();
  await f.getByLabel('Occasion',{exact:true}).fill('Community celebration '+ 'a'.repeat(70));
  await f.getByLabel('City',{exact:true}).fill('Pune');
  await f.getByRole('button',{name:'Find my event team'}).click();
  await page.setViewportSize({width:320,height:1200});
  await f.waitForFunction(()=>innerWidth===288);
  ok(await root.evaluate(e=>e.scrollWidth===e.clientWidth),'Long custom occasion wraps at narrow width');
  await button('Explore').click();
  await page.setViewportSize({width:736,height:1100});
  ok(errors.length===0,'No JavaScript runtime errors during tested interactions');
  return {checks,layouts,errors};
}
